SET search_path TO lms, extensions;

-- Transactional domain workflows for enrollment, curriculum/version changes,
-- progress transitions, and reminder delivery claims.

CREATE TABLE IF NOT EXISTS lms.reminder_deliveries (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  learner_progress_id UUID NOT NULL REFERENCES lms.learner_progress(id) ON DELETE CASCADE,
  reminder_key TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'claimed'
    CHECK (status IN ('claimed', 'sent', 'failed')),
  claimed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  sent_at TIMESTAMPTZ,
  failed_at TIMESTAMPTZ,
  attempts INTEGER NOT NULL DEFAULT 1 CHECK (attempts > 0),
  error_message TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (learner_progress_id, reminder_key)
);

ALTER TABLE lms.reminder_deliveries ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "reminder_deliveries: admin all" ON lms.reminder_deliveries;
CREATE POLICY "reminder_deliveries: admin all" ON lms.reminder_deliveries
  USING (lms.is_admin())
  WITH CHECK (lms.is_admin());

CREATE INDEX IF NOT EXISTS idx_reminder_deliveries_progress_status
  ON lms.reminder_deliveries(learner_progress_id, status);

CREATE INDEX IF NOT EXISTS idx_modules_parent_order_active
  ON lms.modules(parent_id, module_order)
  WHERE deleted_at IS NULL;

ALTER TABLE lms.learner_progress
  DROP CONSTRAINT IF EXISTS learner_progress_timestamp_state_check;

ALTER TABLE lms.learner_progress
  ADD CONSTRAINT learner_progress_timestamp_state_check CHECK (
    (status = 'not_started' AND started_at IS NULL AND completed_at IS NULL)
    OR (status = 'in_progress' AND started_at IS NOT NULL AND completed_at IS NULL)
    OR (status = 'completed' AND started_at IS NOT NULL AND completed_at IS NOT NULL)
  ) NOT VALID;

CREATE OR REPLACE FUNCTION lms.assert_rpc_actor(actor_id UUID)
RETURNS lms.users
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
DECLARE
  actor lms.users%ROWTYPE;
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE = '28000';
  END IF;

  IF auth.uid() IS NOT NULL AND auth.uid() <> actor_id THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO actor
  FROM lms.users
  WHERE id = actor_id
    AND is_active = TRUE
    AND deleted_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'INACTIVE_ACCOUNT' USING ERRCODE = '28000';
  END IF;

  RETURN actor;
END;
$$;

CREATE OR REPLACE FUNCTION lms.actor_can_manage_learner(
  actor_id UUID,
  target_learner_id UUID,
  target_module_id UUID DEFAULT NULL
)
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
SET search_path = lms
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM lms.users actor
    WHERE actor.id = actor_id
      AND actor.is_active = TRUE
      AND actor.deleted_at IS NULL
      AND (
        actor.role = 'admin'
        OR (
          actor.role = 'teacher'
          AND (
            EXISTS (
              SELECT 1
              FROM lms.teacher_assignments ta
              WHERE ta.teacher_id = actor_id
                AND ta.learner_id = target_learner_id
                AND ta.is_active = TRUE
            )
            OR (
              target_module_id IS NOT NULL
              AND EXISTS (
                SELECT 1
                FROM lms.learner_progress lp
                WHERE lp.teacher_id = actor_id
                  AND lp.learner_id = target_learner_id
                  AND lp.module_id = target_module_id
              )
            )
          )
        )
      )
  );
$$;

CREATE OR REPLACE FUNCTION lms.actor_can_manage_event(actor_id UUID, target_event_id UUID)
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
SET search_path = lms
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM lms.users actor
    JOIN lms.events event ON event.id = target_event_id
    WHERE actor.id = actor_id
      AND actor.is_active = TRUE
      AND actor.deleted_at IS NULL
      AND event.deleted_at IS NULL
      AND (
        actor.role = 'admin'
        OR (
          actor.role = 'teacher'
          AND (event.created_by = actor_id OR event.teacher_id = actor_id)
        )
      )
  );
$$;

CREATE OR REPLACE FUNCTION lms.enroll_in_event_atomic(
  actor_id UUID,
  target_event_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms, storage
AS $$
DECLARE
  actor lms.users%ROWTYPE;
  target_event lms.events%ROWTYPE;
  attendance_id UUID;
  progress_row lms.learner_progress%ROWTYPE;
  now_ts TIMESTAMPTZ := NOW();
  already_enrolled BOOLEAN := FALSE;
  progress_status TEXT;
BEGIN
  actor := lms.assert_rpc_actor(actor_id);

  IF actor.role <> 'learner' THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO target_event
  FROM lms.events
  WHERE id = target_event_id
  FOR UPDATE;

  IF NOT FOUND OR target_event.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'EVENT_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF target_event.end_date IS NOT NULL AND target_event.end_date < now_ts THEN
    RAISE EXCEPTION 'EVENT_ENDED' USING ERRCODE = '22023';
  END IF;

  SELECT id INTO attendance_id
  FROM lms.event_attendances
  WHERE event_id = target_event.id
    AND learner_id = actor.id
  FOR UPDATE;

  already_enrolled := FOUND;

  IF NOT already_enrolled THEN
    INSERT INTO lms.event_attendances(event_id, learner_id)
    VALUES (target_event.id, actor.id)
    RETURNING id INTO attendance_id;
  END IF;

  INSERT INTO lms.learner_profiles(user_id, cohort_label)
  VALUES (actor.id, target_event.name)
  ON CONFLICT (user_id) DO UPDATE
    SET cohort_label = EXCLUDED.cohort_label,
        updated_at = now_ts;

  SELECT *
  INTO progress_row
  FROM lms.learner_progress
  WHERE learner_id = actor.id
    AND module_id = target_event.module_id
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO lms.learner_progress(
      learner_id,
      module_id,
      status,
      teacher_id,
      cohort_label,
      started_at
    )
    VALUES (
      actor.id,
      target_event.module_id,
      'in_progress',
      COALESCE(target_event.teacher_id, target_event.created_by),
      target_event.name,
      now_ts
    )
    RETURNING * INTO progress_row;
  ELSE
    UPDATE lms.learner_progress
    SET teacher_id = COALESCE(target_event.teacher_id, target_event.created_by),
        cohort_label = target_event.name,
        updated_at = now_ts
    WHERE id = progress_row.id
    RETURNING * INTO progress_row;
  END IF;

  progress_status := progress_row.status;

  RETURN jsonb_build_object(
    'attendanceId', attendance_id,
    'eventId', target_event.id,
    'moduleId', target_event.module_id,
    'alreadyEnrolled', already_enrolled,
    'progressStatus', progress_status
  );
END;
$$;

CREATE OR REPLACE FUNCTION lms.add_learners_to_event_atomic(
  actor_id UUID,
  target_event_id UUID,
  learner_ids UUID[]
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
DECLARE
  actor lms.users%ROWTYPE;
  target_event lms.events%ROWTYPE;
  unique_count INTEGER;
  eligible_count INTEGER;
  now_ts TIMESTAMPTZ := NOW();
BEGIN
  actor := lms.assert_rpc_actor(actor_id);

  IF NOT lms.actor_can_manage_event(actor.id, target_event_id) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  IF learner_ids IS NULL OR array_length(learner_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('eventId', target_event_id, 'addedCount', 0);
  END IF;

  SELECT COUNT(DISTINCT learner_id)
  INTO unique_count
  FROM unnest(learner_ids) AS learner_id;

  IF unique_count <> array_length(learner_ids, 1) THEN
    RAISE EXCEPTION 'DUPLICATE_LEARNER_IDS' USING ERRCODE = '22023';
  END IF;

  SELECT *
  INTO target_event
  FROM lms.events
  WHERE id = target_event_id
  FOR UPDATE;

  IF NOT FOUND OR target_event.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'EVENT_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF target_event.end_date IS NOT NULL AND target_event.end_date < now_ts THEN
    RAISE EXCEPTION 'EVENT_ENDED' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*)
  INTO eligible_count
  FROM lms.users u
  WHERE u.id = ANY(learner_ids)
    AND u.role = 'learner'
    AND u.is_active = TRUE
    AND u.deleted_at IS NULL;

  IF eligible_count <> unique_count THEN
    RAISE EXCEPTION 'INELIGIBLE_LEARNER' USING ERRCODE = '22023';
  END IF;

  INSERT INTO lms.event_attendances(event_id, learner_id)
  SELECT target_event.id, learner_id
  FROM unnest(learner_ids) AS learner_id
  ON CONFLICT (event_id, learner_id) DO NOTHING;

  INSERT INTO lms.learner_profiles(user_id, cohort_label)
  SELECT learner_id, target_event.name
  FROM unnest(learner_ids) AS learner_id
  ON CONFLICT (user_id) DO UPDATE
    SET cohort_label = EXCLUDED.cohort_label,
        updated_at = now_ts;

  INSERT INTO lms.learner_progress(
    learner_id,
    module_id,
    status,
    teacher_id,
    cohort_label,
    started_at
  )
  SELECT
    learner_id,
    target_event.module_id,
    'in_progress',
    COALESCE(target_event.teacher_id, target_event.created_by),
    target_event.name,
    now_ts
  FROM unnest(learner_ids) AS learner_id
  ON CONFLICT (learner_id, module_id) DO UPDATE
    SET teacher_id = EXCLUDED.teacher_id,
        cohort_label = EXCLUDED.cohort_label,
        updated_at = now_ts;

  RETURN jsonb_build_object(
    'eventId', target_event.id,
    'moduleId', target_event.module_id,
    'addedCount', unique_count
  );
END;
$$;

CREATE OR REPLACE FUNCTION lms.create_module_atomic(
  actor_id UUID,
  module_title TEXT,
  module_code TEXT DEFAULT NULL,
  module_description TEXT DEFAULT NULL,
  estimated_minutes INTEGER DEFAULT NULL,
  reminder_days INTEGER DEFAULT NULL,
  parent_module_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
DECLARE
  actor lms.users%ROWTYPE;
  parent_row lms.modules%ROWTYPE;
  next_order INTEGER;
  new_module lms.modules%ROWTYPE;
BEGIN
  actor := lms.assert_rpc_actor(actor_id);

  IF actor.role <> 'admin' THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  IF module_title IS NULL OR btrim(module_title) = '' THEN
    RAISE EXCEPTION 'VALIDATION_ERROR' USING ERRCODE = '22023';
  END IF;

  IF parent_module_id IS NOT NULL THEN
    SELECT *
    INTO parent_row
    FROM lms.modules
    WHERE id = parent_module_id
      AND deleted_at IS NULL
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PARENT_MODULE_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('modules-order'), hashtext(COALESCE(parent_module_id::TEXT, 'root')));

  SELECT COALESCE(MAX(module_order), 0) + 1
  INTO next_order
  FROM lms.modules
  WHERE deleted_at IS NULL
    AND (
      (parent_module_id IS NULL AND parent_id IS NULL)
      OR parent_id = parent_module_id
    );

  INSERT INTO lms.modules(
    title,
    module_code,
    description,
    estimated_minutes,
    reminder_days,
    parent_id,
    module_order,
    is_published,
    created_by
  )
  VALUES (
    module_title,
    module_code,
    module_description,
    estimated_minutes,
    reminder_days,
    parent_module_id,
    next_order,
    parent_module_id IS NULL,
    actor.id
  )
  RETURNING * INTO new_module;

  RETURN jsonb_build_object('id', new_module.id, 'moduleOrder', new_module.module_order);
END;
$$;

CREATE OR REPLACE FUNCTION lms.reorder_modules_atomic(
  actor_id UUID,
  parent_module_id UUID,
  ordered_module_ids UUID[]
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
DECLARE
  actor lms.users%ROWTYPE;
  requested_count INTEGER;
  scope_count INTEGER;
BEGIN
  actor := lms.assert_rpc_actor(actor_id);

  IF actor.role <> 'admin' THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  IF ordered_module_ids IS NULL OR array_length(ordered_module_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'INVALID_REORDER' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(DISTINCT module_id)
  INTO requested_count
  FROM unnest(ordered_module_ids) AS module_id;

  IF requested_count <> array_length(ordered_module_ids, 1) THEN
    RAISE EXCEPTION 'DUPLICATE_MODULE_IDS' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('modules-order'), hashtext(COALESCE(parent_module_id::TEXT, 'root')));

  SELECT COUNT(*)
  INTO scope_count
  FROM lms.modules
  WHERE deleted_at IS NULL
    AND (
      (parent_module_id IS NULL AND parent_id IS NULL)
      OR parent_id = parent_module_id
    );

  IF scope_count <> requested_count THEN
    RAISE EXCEPTION 'REORDER_SCOPE_MISMATCH' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(ordered_module_ids) AS requested(id)
    LEFT JOIN lms.modules m
      ON m.id = requested.id
      AND m.deleted_at IS NULL
      AND (
        (parent_module_id IS NULL AND m.parent_id IS NULL)
        OR m.parent_id = parent_module_id
      )
    WHERE m.id IS NULL
  ) THEN
    RAISE EXCEPTION 'INVALID_REORDER_MODULE' USING ERRCODE = '22023';
  END IF;

  PERFORM 1
  FROM lms.modules
  WHERE deleted_at IS NULL
    AND (
      (parent_module_id IS NULL AND parent_id IS NULL)
      OR parent_id = parent_module_id
    )
  FOR UPDATE;

  WITH ordered AS (
    SELECT id, ordinality::INTEGER AS new_order
    FROM unnest(ordered_module_ids) WITH ORDINALITY AS input(id, ordinality)
  )
  UPDATE lms.modules m
  SET module_order = ordered.new_order,
      updated_at = NOW()
  FROM ordered
  WHERE m.id = ordered.id;

  RETURN jsonb_build_object('parentModuleId', parent_module_id, 'reorderedCount', requested_count);
END;
$$;

CREATE OR REPLACE FUNCTION lms.finalize_module_version_atomic(
  actor_id UUID,
  target_module_id UUID,
  target_storage_path TEXT,
  target_file_name TEXT,
  target_language TEXT DEFAULT 'en'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms, storage
AS $$
DECLARE
  actor lms.users%ROWTYPE;
  target_module lms.modules%ROWTYPE;
  existing_version lms.module_versions%ROWTYPE;
  new_version lms.module_versions%ROWTYPE;
  next_version INTEGER;
  object_record storage.objects%ROWTYPE;
  file_size BIGINT;
BEGIN
  actor := lms.assert_rpc_actor(actor_id);

  IF actor.role <> 'admin' THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  IF target_language NOT IN ('en', 'zh') THEN
    RAISE EXCEPTION 'INVALID_LANGUAGE' USING ERRCODE = '22023';
  END IF;

  IF target_storage_path IS NULL
    OR target_storage_path LIKE '%..%'
    OR target_storage_path NOT LIKE ('modules/' || target_module_id::TEXT || '/' || target_language || '/%') THEN
    RAISE EXCEPTION 'INVALID_STORAGE_PATH' USING ERRCODE = '22023';
  END IF;

  IF target_file_name IS NULL OR lower(target_file_name) NOT LIKE '%.pdf' THEN
    RAISE EXCEPTION 'INVALID_FILE_NAME' USING ERRCODE = '22023';
  END IF;

  SELECT *
  INTO target_module
  FROM lms.modules
  WHERE id = target_module_id
  FOR UPDATE;

  IF NOT FOUND OR target_module.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'MODULE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  SELECT *
  INTO object_record
  FROM storage.objects
  WHERE bucket_id = 'study-notes'
    AND name = target_storage_path
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'UPLOAD_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  file_size := NULLIF(object_record.metadata->>'size', '')::BIGINT;

  SELECT *
  INTO existing_version
  FROM lms.module_versions
  WHERE module_id = target_module_id
    AND storage_path = target_storage_path
    AND language = target_language
  FOR UPDATE;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'moduleVersionId', existing_version.id,
      'moduleId', existing_version.module_id,
      'version', existing_version.version,
      'language', existing_version.language,
      'alreadyFinalized', TRUE
    );
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('module-version'), hashtext(target_module_id::TEXT || ':' || target_language));

  SELECT COALESCE(MAX(version), 0) + 1
  INTO next_version
  FROM lms.module_versions
  WHERE module_id = target_module_id
    AND language = target_language;

  UPDATE lms.module_versions
  SET is_current = FALSE
  WHERE module_id = target_module_id
    AND language = target_language
    AND is_current = TRUE;

  INSERT INTO lms.module_versions(
    module_id,
    storage_path,
    file_name,
    file_size,
    uploaded_by,
    version,
    language,
    is_current
  )
  VALUES (
    target_module_id,
    target_storage_path,
    target_file_name,
    file_size,
    actor.id,
    next_version,
    target_language,
    TRUE
  )
  RETURNING * INTO new_version;

  UPDATE lms.modules
  SET is_published = TRUE,
      updated_at = NOW()
  WHERE id = target_module_id;

  RETURN jsonb_build_object(
    'moduleVersionId', new_version.id,
    'moduleId', new_version.module_id,
    'version', new_version.version,
    'language', new_version.language,
    'alreadyFinalized', FALSE
  );
END;
$$;

CREATE OR REPLACE FUNCTION lms.start_module_atomic(actor_id UUID, target_module_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
DECLARE
  actor lms.users%ROWTYPE;
  target_module lms.modules%ROWTYPE;
  progress_row lms.learner_progress%ROWTYPE;
  now_ts TIMESTAMPTZ := NOW();
BEGIN
  actor := lms.assert_rpc_actor(actor_id);

  SELECT *
  INTO target_module
  FROM lms.modules
  WHERE id = target_module_id
    AND deleted_at IS NULL
    AND is_published = TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'MODULE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  SELECT *
  INTO progress_row
  FROM lms.learner_progress
  WHERE learner_id = actor.id
    AND module_id = target_module_id
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO lms.learner_progress(learner_id, module_id, status, started_at)
    VALUES (actor.id, target_module_id, 'in_progress', now_ts)
    RETURNING * INTO progress_row;
  ELSIF progress_row.status = 'not_started' THEN
    UPDATE lms.learner_progress
    SET status = 'in_progress',
        started_at = COALESCE(started_at, now_ts),
        completed_at = NULL,
        updated_at = now_ts
    WHERE id = progress_row.id
    RETURNING * INTO progress_row;
  END IF;

  RETURN jsonb_build_object(
    'learnerProgressId', progress_row.id,
    'moduleId', target_module_id,
    'status', progress_row.status
  );
END;
$$;

CREATE OR REPLACE FUNCTION lms.complete_module_atomic(
  actor_id UUID,
  target_learner_id UUID,
  target_module_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
DECLARE
  actor lms.users%ROWTYPE;
  progress_row lms.learner_progress%ROWTYPE;
  learner_exists BOOLEAN;
  module_exists BOOLEAN;
  now_ts TIMESTAMPTZ := NOW();
BEGIN
  actor := lms.assert_rpc_actor(actor_id);

  SELECT EXISTS (
    SELECT 1 FROM lms.users
    WHERE id = target_learner_id
      AND role = 'learner'
      AND is_active = TRUE
      AND deleted_at IS NULL
  ) INTO learner_exists;

  IF NOT learner_exists THEN
    RAISE EXCEPTION 'LEARNER_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM lms.modules
    WHERE id = target_module_id
      AND deleted_at IS NULL
  ) INTO module_exists;

  IF NOT module_exists THEN
    RAISE EXCEPTION 'MODULE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF NOT lms.actor_can_manage_learner(actor.id, target_learner_id, target_module_id) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO progress_row
  FROM lms.learner_progress
  WHERE learner_id = target_learner_id
    AND module_id = target_module_id
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO lms.learner_progress(
      learner_id,
      module_id,
      status,
      started_at,
      completed_at,
      marked_by
    )
    VALUES (
      target_learner_id,
      target_module_id,
      'completed',
      now_ts,
      now_ts,
      actor.id
    )
    RETURNING * INTO progress_row;
  ELSIF progress_row.status <> 'completed' THEN
    UPDATE lms.learner_progress
    SET status = 'completed',
        started_at = COALESCE(started_at, now_ts),
        completed_at = now_ts,
        marked_by = actor.id,
        updated_at = now_ts
    WHERE id = progress_row.id
    RETURNING * INTO progress_row;
  END IF;

  RETURN jsonb_build_object(
    'learnerProgressId', progress_row.id,
    'moduleId', target_module_id,
    'learnerId', target_learner_id,
    'status', progress_row.status
  );
END;
$$;

CREATE OR REPLACE FUNCTION lms.reopen_module_atomic(
  actor_id UUID,
  target_learner_id UUID,
  target_module_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
DECLARE
  actor lms.users%ROWTYPE;
  progress_row lms.learner_progress%ROWTYPE;
  learner_exists BOOLEAN;
  module_exists BOOLEAN;
  now_ts TIMESTAMPTZ := NOW();
BEGIN
  actor := lms.assert_rpc_actor(actor_id);

  SELECT EXISTS (
    SELECT 1 FROM lms.users
    WHERE id = target_learner_id
      AND role = 'learner'
      AND is_active = TRUE
      AND deleted_at IS NULL
  ) INTO learner_exists;

  IF NOT learner_exists THEN
    RAISE EXCEPTION 'LEARNER_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM lms.modules
    WHERE id = target_module_id
      AND deleted_at IS NULL
  ) INTO module_exists;

  IF NOT module_exists THEN
    RAISE EXCEPTION 'MODULE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF NOT lms.actor_can_manage_learner(actor.id, target_learner_id, target_module_id) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO progress_row
  FROM lms.learner_progress
  WHERE learner_id = target_learner_id
    AND module_id = target_module_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'learnerProgressId', NULL,
      'moduleId', target_module_id,
      'learnerId', target_learner_id,
      'status', 'not_started'
    );
  ELSIF progress_row.status = 'completed' THEN
    UPDATE lms.learner_progress
    SET status = 'in_progress',
        started_at = COALESCE(started_at, now_ts),
        completed_at = NULL,
        marked_by = NULL,
        updated_at = now_ts
    WHERE id = progress_row.id
    RETURNING * INTO progress_row;
  END IF;

  RETURN jsonb_build_object(
    'learnerProgressId', progress_row.id,
    'moduleId', target_module_id,
    'learnerId', target_learner_id,
    'status', progress_row.status
  );
END;
$$;

CREATE OR REPLACE FUNCTION lms.save_reflection_atomic(
  actor_id UUID,
  target_module_id UUID,
  reflection_notes TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
DECLARE
  actor lms.users%ROWTYPE;
  target_module lms.modules%ROWTYPE;
  progress_row lms.learner_progress%ROWTYPE;
  now_ts TIMESTAMPTZ := NOW();
BEGIN
  actor := lms.assert_rpc_actor(actor_id);

  SELECT *
  INTO target_module
  FROM lms.modules
  WHERE id = target_module_id
    AND deleted_at IS NULL
    AND is_published = TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'MODULE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO lms.learner_progress(learner_id, module_id, status, notes)
  VALUES (actor.id, target_module_id, 'not_started', reflection_notes)
  ON CONFLICT (learner_id, module_id) DO UPDATE
    SET notes = EXCLUDED.notes,
        updated_at = now_ts
  RETURNING * INTO progress_row;

  RETURN jsonb_build_object(
    'learnerProgressId', progress_row.id,
    'moduleId', target_module_id,
    'status', progress_row.status
  );
END;
$$;

CREATE OR REPLACE FUNCTION lms.claim_due_module_reminders(
  batch_limit INTEGER DEFAULT 100,
  claim_token UUID DEFAULT gen_random_uuid()
)
RETURNS TABLE (
  delivery_id UUID,
  learner_progress_id UUID,
  learner_id UUID,
  learner_email TEXT,
  learner_name TEXT,
  module_id UUID,
  module_title TEXT,
  reminder_key TEXT
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
BEGIN
  IF batch_limit IS NULL OR batch_limit < 1 OR batch_limit > 500 THEN
    RAISE EXCEPTION 'INVALID_BATCH_LIMIT' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH due AS (
    SELECT
      lp.id AS progress_id,
      lp.learner_id,
      u.email,
      u.full_name,
      m.id AS module_id,
      m.title,
      (lp.id::TEXT || ':' || CURRENT_DATE::TEXT) AS occurrence_key
    FROM lms.learner_progress lp
    JOIN lms.modules m ON m.id = lp.module_id
    JOIN lms.users u ON u.id = lp.learner_id
    WHERE lp.status = 'in_progress'
      AND m.deleted_at IS NULL
      AND m.reminder_days IS NOT NULL
      AND u.is_active = TRUE
      AND u.deleted_at IS NULL
      AND FLOOR(EXTRACT(EPOCH FROM (NOW() - COALESCE(lp.started_at, lp.created_at))) / 86400) >= m.reminder_days
      AND (
        lp.last_reminded_at IS NULL
        OR FLOOR(EXTRACT(EPOCH FROM (NOW() - lp.last_reminded_at)) / 86400) >= m.reminder_days
      )
    ORDER BY COALESCE(lp.last_reminded_at, lp.started_at, lp.created_at) ASC
    LIMIT batch_limit
  ),
  claimed AS (
    INSERT INTO lms.reminder_deliveries(
      learner_progress_id,
      reminder_key,
      status,
      claimed_at,
      attempts,
      error_message,
      updated_at
    )
    SELECT
      due.progress_id,
      due.occurrence_key,
      'claimed',
      NOW(),
      1,
      claim_token::TEXT,
      NOW()
    FROM due
    ON CONFLICT (learner_progress_id, reminder_key) DO UPDATE
      SET status = 'claimed',
          claimed_at = NOW(),
          attempts = lms.reminder_deliveries.attempts + 1,
          error_message = claim_token::TEXT,
          updated_at = NOW()
      WHERE lms.reminder_deliveries.status = 'failed'
        OR (
          lms.reminder_deliveries.status = 'claimed'
          AND lms.reminder_deliveries.claimed_at < NOW() - INTERVAL '30 minutes'
        )
    RETURNING
      id,
      learner_progress_id,
      reminder_key,
      error_message
  )
  SELECT
    claimed.id,
    due.progress_id,
    due.learner_id,
    due.email,
    COALESCE(due.full_name, 'Learner'),
    due.module_id,
    due.title,
    claimed.reminder_key
  FROM claimed
  JOIN due
    ON due.progress_id = claimed.learner_progress_id
   AND due.occurrence_key = claimed.reminder_key
  WHERE claimed.error_message = claim_token::TEXT;
END;
$$;

CREATE OR REPLACE FUNCTION lms.mark_reminder_sent(delivery_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
DECLARE
  delivery lms.reminder_deliveries%ROWTYPE;
BEGIN
  SELECT *
  INTO delivery
  FROM lms.reminder_deliveries
  WHERE id = delivery_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'REMINDER_DELIVERY_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  UPDATE lms.reminder_deliveries
  SET status = 'sent',
      sent_at = NOW(),
      failed_at = NULL,
      error_message = NULL,
      updated_at = NOW()
  WHERE id = delivery.id;

  UPDATE lms.learner_progress
  SET last_reminded_at = NOW(),
      updated_at = NOW()
  WHERE id = delivery.learner_progress_id;
END;
$$;

CREATE OR REPLACE FUNCTION lms.mark_reminder_failed(delivery_id UUID, failure_message TEXT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
BEGIN
  UPDATE lms.reminder_deliveries
  SET status = 'failed',
      failed_at = NOW(),
      error_message = left(COALESCE(failure_message, 'Unknown reminder failure'), 1000),
      updated_at = NOW()
  WHERE id = delivery_id
    AND status = 'claimed';
END;
$$;

