REVOKE ALL ON FUNCTION lms.start_module_atomic(UUID, UUID) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION lms.complete_module_atomic(UUID, UUID, UUID) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION lms.reopen_module_atomic(UUID, UUID, UUID) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION lms.save_reflection_atomic(UUID, UUID, TEXT) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION lms.claim_due_module_reminders(INTEGER, UUID) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION lms.mark_reminder_sent(UUID) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION lms.mark_reminder_failed(UUID, TEXT) FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION lms.actor_can_manage_learner(UUID, UUID, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION lms.actor_can_manage_event(UUID, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION lms.enroll_in_event_atomic(UUID, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION lms.add_learners_to_event_atomic(UUID, UUID, UUID[]) TO authenticated;
GRANT EXECUTE ON FUNCTION lms.create_module_atomic(UUID, TEXT, TEXT, TEXT, INTEGER, INTEGER, UUID) TO authenticated;
