GRANT EXECUTE ON FUNCTION lms.finalize_module_version_atomic(UUID, UUID, TEXT, TEXT, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION lms.start_module_atomic(UUID, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION lms.complete_module_atomic(UUID, UUID, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION lms.reopen_module_atomic(UUID, UUID, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION lms.save_reflection_atomic(UUID, UUID, TEXT) TO authenticated;

GRANT EXECUTE ON FUNCTION lms.claim_due_module_reminders(INTEGER, UUID) TO service_role;
GRANT EXECUTE ON FUNCTION lms.mark_reminder_sent(UUID) TO service_role;
GRANT EXECUTE ON FUNCTION lms.mark_reminder_failed(UUID, TEXT) TO service_role;;
